window.kbPageData["views/entry/k-2e84af61a019e22a"] = {"key":"entry/k-2e84af61a019e22a","state":{"route":"entry/k-2e84af61a019e22a"},"node":{"id":"k-2e84af61a019e22a","mode":"k","title":"子集与交集","type":"原理与机制","domain":"数学","reading":"","intro":"","priority":100,"aliases":["若一个集合包含于另一个集合，两者的交集等于被包含的集合"],"qs":["国考 2024 地市级 行测#68"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"若集合A是集合B的子集，则A∩B＝A。对任意集合C，也有A∩B∩C＝A∩C。","review":{"definition":"若集合A是集合B的子集，则A∩B＝A。对任意集合C，也有A∩B∩C＝A∩C。","explanation":"本题中，会俄语的学生都会英语，所以同时会俄语和法语的学生恰好是三种语言都会的50人。这50人占会俄语学生的一半，另一半50人只会俄语和英语。只会两种语言的共有100人，余下50人只会英语和法语。英法交集因此有100人，按会英语者中一半会法语可得会英语者共200人，其中50人只会英语。只会一种语言的150人中，余下100人只会法语。会法语的共50＋50＋100＝200人，选B。","references":[],"evidence":"会俄语的学生包含于会英语的学生","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"国考 2024 地市级 行测#68":{"paper":"国考 2024 地市级 行测","n":68,"mod":"数量关系","src":["92d0b72e86a6a33d568d.pdf",12],"asrc":["e1792c53900a45f1b9fa.pdf",20],"card":"6f20278fb310ec4c8aa778a3","links":[{"id":"k-2e84af61a019e22a","role":"解题依据","why":"俄语集合包含于英语集合，因此会俄语又会法语的学生都落在三语交集内。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-2e84af61a019e22a":[["国考 2024 地市级 行测#68"]]}};
